import math

def test_unpulled_is_infinite():
    s = solution.ucb_scores([0.5, 0.6], [10, 0])
    assert s[1] == float("inf")

def test_uncertain_arm_first():
    s = solution.ucb_scores([0.6, 0.55], [100, 4])
    assert s[1] > s[0]

def test_no_pulls_raises():
    try:
        solution.ucb_scores([0.5, 0.5], [0, 0])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_length_mismatch():
    try:
        solution.ucb_scores([0.5], [1, 2])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_bonus_shrinks():
    s = solution.ucb_scores([0.5, 0.5], [10, 100])
    assert s[0] > s[1]

def test_returns_floats():
    s = solution.ucb_scores([0.5], [10])
    assert all(isinstance(v, float) for v in s)
